\begin{proposition}[B.4.1; Proved]\label{st:B.4.1}
For each member of the retained $(3,4)$ family, $\operatorname{Aut}(X_c)$, including all its components, is $\mathbb C/\mathbb Z\simeq\mathbb C^*$. Its action on the ordinary fibres is $\zeta\mapsto\zeta+be$, and the exponential group isomorphism is $b\mapsto e^{2\pi ib}$.
\end{proposition}

\begin{proposition}[D.1.2; Known, with derivation]\label{st:D.1.2}
The locus on \(B^\circ\) where \(P(t)\) is torsion is countable and dense.
Every fibre over this locus is an abelian surface. The divisor on the
smooth base cut out by \(6kP=O\) has degree \(3k^2-1\), including local
intersection multiplicity, for every positive integer \(k\).
\end{proposition}

\begin{theorem}[D.1.3; Refuted]\label{st:D.1.3}
The assertion in Lead 6 that \emph{existence of a surjection onto the
specified \(E_t\) with elliptic kernel} is equivalent to \(6P(t)=O\)
is false. It remains true for the specified projection in D.1.1.
\end{theorem}

\begin{proposition}[D.2.1; Proved]\label{st:D.2.1}
For a standard-twist member \(X_c\) with underlying manifold \(S^6\),
every compact irreducible complex curve lies in one fibre of \(f\), and
every compact irreducible complex surface is one of the reduced fibres.
\end{proposition}

\begin{proposition}[F.2.3; Proved]\label{st:F.2.3}
The positive sign region admits the global period chart
\[
 \mathcal O_+=\left\{
 (\tau,\mu,\beta)\in\mathbb C^3:
 \operatorname{Im}\tau>0,\quad
 \operatorname{Im}\beta-\frac{6(\operatorname{Im}\mu)^2}
 {\operatorname{Im}\tau}<0\right\},
\]
represented by the matrix $\Pi$ in the question.  In this chart,
\begin{equation}\label{eq:F-qD}
 q_e(J)=-\frac6D.
\end{equation}
Every admissible period $\Pi_c(z)$ belongs to $\mathcal O_+$, for every
admissible $c$.  Thus this single maximal proper-action open set contains
all the period images in question.
\end{proposition}
